def choose_move(observation):
    def sget(obj, key, default=None):
        try:
            return obj.get(key, default)
        except Exception:
            return default

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return default
        return default

    def clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = sget(observation, "environment_name", "resource_collection")
    sx, sy = pos(sget(observation, "self_position", (0, 0)))
    ox, oy = pos(sget(observation, "opponent_position", (sx, sy)))

    gw = sget(observation, "grid_width", 0)
    gh = sget(observation, "grid_height", 0)
    try:
        gw = int(gw)
    except Exception:
        gw = 0
    try:
        gh = int(gh)
    except Exception:
        gh = 0

    if env == "pursuit_evasion":
        role = sget(observation, "self_role", "pursuer")
        if role == "pursuer":
            return [clamp_step(sx, ox), clamp_step(sy, oy)]
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        best = corners[0]
        best_d = -1
        for c in corners:
            d = manhattan(c, (ox, oy))
            if d > best_d:
                best_d = d
                best = c
        return [clamp_step(sx, best[0]), clamp_step(sy, best[1])]

    if env == "territory_control":
        targets = sget(observation, "unclaimed_cells", None)
        if not targets:
            targets = sget(observation, "opponent_territory", None)
        if not targets:
            targets = sget(observation, "enemy_territory", None)
        if not targets:
            if gw and gh:
                return [clamp_step(sx, gw // 2), clamp_step(sy, gh // 2)]
            return [0, 0]

        best = None
        best_score = None
        for t in targets:
            tx, ty = pos(t, (sx, sy))
            # Prefer close targets, but lightly prefer moving away from opponent.
            score = manhattan((sx, sy), (tx, ty)) - 0.25 * manhattan((ox, oy), (tx, ty))
            if best_score is None or score < best_score:
                best_score = score
                best = (tx, ty)
        return [clamp_step(sx, best[0]), clamp_step(sy, best[1])]

    resources = sget(observation, "resources", None)
    if not resources:
        resources = sget(observation, "resource_positions", None)
    if resources:
        best = None
        best_d = None
        for r in resources:
            rx, ry = pos(r, (sx, sy))
            d = manhattan((sx, sy), (rx, ry))
            if best_d is None or d < best_d:
                best_d = d
                best = (rx, ry)
        return [clamp_step(sx, best[0]), clamp_step(sy, best[1])]

    # Fallback: move toward opponent in unknown settings to keep pressure.
    return [clamp_step(sx, ox), clamp_step(sy, oy)]

